const csvText = $input.first().json.data;

const cleaned = csvText.replace(/^\uFEFF/, '');
const lines = cleaned.trim().split('\n');
const headers = lines[0].split(';').map(h => h.trim());

const rows = [];
for (let i = 1; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue;
  const values = line.split(';');
  const row = {};
  headers.forEach((h, idx) => {
    let val = values[idx]?.trim().replace('\r', '') ?? '';
    if (['aestheticsScore', 'colorSaturation', 'visualComplexity'].includes(h)) {
      val = val.replace(',', '.');
    }
    row[h] = val;
  });
  rows.push(row);
}

return rows.map(r => ({ json: r }));

// Get ALL items from both connected nodes
const allItems = $input.all().map(i => i.json);

// Split into two datasets by which fields they contain
// Assignment rows have: workerId, qualityScore, realismScore
// Image rows have: model, dataset, aestheticsScore
const assignRows = allItems.filter(r => r.workerId !== undefined);
const imageRows  = allItems.filter(r => r.model !== undefined);

// Safety check — return diagnostic if either is empty
if (assignRows.length === 0 || imageRows.length === 0) {
  return [{ json: {
    error: 'One dataset is empty',
    assignCount: assignRows.length,
    imageCount: imageRows.length,
    totalItems: allItems.length,
    sampleKeys: allItems.length > 0 ? Object.keys(allItems[0]) : []
  }}];
}

// Build image lookup map
const imageMap = {};
for (const img of imageRows) {
  imageMap[img.filename] = img;
}

// Merge on filename
const merged = assignRows.map(a => {
  const img = imageMap[a.filename] || {};
  return {
    filename:        a.filename,
    workerId:        a.workerId,
    assignmentId:    a.assignmentId,
    qualityScore:    parseInt(a.qualityScore, 10),
    realismScore:    parseInt(a.realismScore, 10),
    model:           img.model        || '',
    dataset:         img.dataset      || '',
    aestheticsScore: parseFloat(img.aestheticsScore || '0'),
    hasFace:         img.hasFace      === 'TRUE',
    hasText:         img.hasText      === 'TRUE',
  };
}).filter(r => r.model !== '' && !isNaN(r.qualityScore));

// Stats helper
function stats(values) {
  const n = values.length;
  if (n === 0) return { mean: 0, std: 0, n: 0 };
  const mean = values.reduce((s, v) => s + v, 0) / n;
  const std  = Math.sqrt(values.reduce((s, v) => s + (v - mean) ** 2, 0) / n);
  return { mean: parseFloat(mean.toFixed(3)), std: parseFloat(std.toFixed(3)), n };
}

// Per-model stats
const modelGroups = {};
for (const row of merged) {
  if (!modelGroups[row.model]) modelGroups[row.model] = { quality: [], realism: [] };
  modelGroups[row.model].quality.push(row.qualityScore);
  modelGroups[row.model].realism.push(row.realismScore);
}

const modelRanking = Object.entries(modelGroups).map(([model, d]) => ({
  model,
  quality: stats(d.quality),
  realism: stats(d.realism),
})).sort((a, b) => b.quality.mean - a.quality.mean);

// Rater bias detection
const imageGroups = {};
for (const row of merged) {
  if (!imageGroups[row.filename]) imageGroups[row.filename] = [];
  imageGroups[row.filename].push(row.qualityScore);
}
const imageMeans = {};
for (const [fn, scores] of Object.entries(imageGroups)) {
  imageMeans[fn] = scores.reduce((s, v) => s + v, 0) / scores.length;
}

const workerDeviations = {};
for (const row of merged) {
  const dev = row.qualityScore - imageMeans[row.filename];
  if (!workerDeviations[row.workerId]) workerDeviations[row.workerId] = [];
  workerDeviations[row.workerId].push(dev);
}

const biasFlags = [];
for (const [worker, devs] of Object.entries(workerDeviations)) {
  if (devs.length < 5) continue;
  const avgDev = devs.reduce((s, v) => s + v, 0) / devs.length;
  if (Math.abs(avgDev) > 1.5) {
    biasFlags.push({
      workerId:     worker,
      avgDeviation: parseFloat(avgDev.toFixed(2)),
      ratingsCount: devs.length,
      type:         avgDev < 0 ? 'harsh_rater' : 'lenient_rater',
    });
  }
}
biasFlags.sort((a, b) => Math.abs(b.avgDeviation) - Math.abs(a.avgDeviation));

return [{ json: {
  runTimestamp: new Date().toISOString(),
  totalImages:  Object.keys(imageGroups).length,
  totalRatings: merged.length,
  totalModels:  modelRanking.length,
  topModel:     modelRanking[0]?.model || 'unknown',
  modelRanking,
  biasFlags:    biasFlags.slice(0, 10),
  datasetBreakdown: {
    amazon:      merged.filter(r => r.dataset === 'amazon').length,
    booking_com: merged.filter(r => r.dataset === 'booking_com').length,
  }
}}];

