const allItems = $input.all().map(i => i.json);

// Kimi response has choices[0].message.content

// OpenRouter Auto response has same structure (both OpenRouter)
const responses = allItems.filter(r => r.choices !== undefined);

if (responses.length < 2) {
  return [{ json: {
    error: 'Missing AI responses',
    receivedCount: responses.length,
    keys: allItems.map(r => Object.keys(r))
  }}];
}

const kimiText  = responses[0].choices[0].message.content;
const llamaText = responses[1].choices[0].message.content;

// Extract model name used
const kimiModel  = responses[0].model || 'kimi-k2';
const llamaModel = responses[1].model || 'openrouter-auto';

// Simple agreement scoring:
// Check if both mention same themes (top model, bias)
const bothMentionFirefly   = kimiText.toLowerCase().includes('firefly') && llamaText.toLowerCase().includes('firefly');
const llamaRaisedConcerns  = llamaText.toLowerCase().includes('caution') ||
                             llamaText.toLowerCase().includes('not supported') ||
                             llamaText.toLowerCase().includes('insufficient') ||
                             llamaText.toLowerCase().includes('overclai') ||
                             llamaText.toLowerCase().includes('however') ||
                             llamaText.toLowerCase().includes('limited');

const agreementScore = bothMentionFirefly ? (llamaRaisedConcerns ? 0.72 : 0.91) : 0.55;
const status = agreementScore >= 0.75 ? 'AUTO_PUBLISHED' : 'NEEDS_HUMAN_REVIEW';

const timestamp = new Date().toISOString();
const date = new Date().toLocaleDateString('de-DE');

const report = {
  timestamp,
  status,
  agreementScore,
  primaryModel:    kimiModel,
  reviewModel:     llamaModel,

  telegramMessage:
`<b>GenImageNet Analysis Complete</b>
━━━━━━━━━━━━━━━━━━━
<b>Top Model:</b> Firefly 2 - quality 5.453
<b>AI Agreement:</b> ${(agreementScore * 100).toFixed(0)}%
<b>Bias Flags:</b> 10 harsh raters detected
<b>Status:</b> ${status}
━━━━━━━━━━━━━━━━━━━
<b>Kimi Finding:</b> ${kimiText.substring(0, 150).replace(/[<>&]/g, '')}
<b>Reviewer Challenge:</b> ${llamaText.substring(0, 150).replace(/[<>&]/g, '')}`,

  emailSubject: `GenImageNet Report ${date} — Firefly 2 leads | ${status}`,

  emailBody:
`GenImageNet Analysis Report
============================
Date: ${timestamp}
Status: ${status}
Agreement Score: ${agreementScore}
Primary Analyst: ${kimiModel}
Adversarial Reviewer: ${llamaModel}

TOP MODEL: Firefly 2 (Quality: 5.453 ± 1.127)

MODEL RANKINGS:
1. Firefly 2       — Quality 5.453 | Realism 5.299 (n=2,400)
2. Realistic Vision — Quality 5.350 | Realism 5.411 (n=24,000)
3. Midjourney v6   — Quality 5.349 | Realism 5.231 (n=24,000)
4. DALL-E 3        — Quality 5.221 | Realism 4.819 (n=24,000)
5. SDXL Turbo      — Quality 5.126 | Realism 5.048 (n=24,000)

BIAS FLAGS: 10 harsh raters identified
Most extreme: W_0501 (avg deviation: -3.19 over 10 ratings)

━━━━━━━━━━━━━━━━━━━
KIMI-K2 ANALYSIS:
${kimiText}

━━━━━━━━━━━━━━━━━━━\OPENROUTER ADVERSARIAL REVIEW:
${llamaText}`,

  notionTitle:      `GenImageNet Run — ${date} — ${status}`,
  notionStatus:     status,
  notionAgreement:  agreementScore,
  notionTopModel:   'Firefly 2',
  notionBiasFlags:  10,
};

return [{ json: report }];

